mapper.delete:
delete from
CHB_PRD_POSITION_TOTAL
where CDATE >= #{cdate,jdbcType=DATE}

   and PROD_ID in 

       #{accountid}

mapper.select:
SELECT NVL(DEAL.FPROD_ID,DEAL.PROD_ID) prodId, DEAL.ISSUE_PARTY_ID issuePartyId, DECODE(DEAL.TRADE_TYPE,'04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE) settdateDate, DEAL.CCY ccy, SUM(NVL(decode(DEAL.TRADE_TYPE,'14',0,'15',0,DEAL.TRADE_AMT),0)) tradeAmt, SUM(NVL(DEAL.TRADE_QTY,0)) tradeQty, SUM(NVL(DEAL.INT_AMT,0)) intAmt, INFO.PRODTYPE prodType, DEAL.ORG_CODE orgCode, SUM(NVL(DEAL.TRADE_COST,0)) tradeCost FROM CHB_PRD_DEAL_TOTAL DEAL
LEFT JOIN CHB_PRD_BASEINFO INFO ON NVL(DEAL.FPROD_ID,DEAL.PROD_ID) = INFO.PROD_ID AND INFO.STATUS!='D'
WHERE DEAL.STATUS != 'D' AND DECODE(DEAL.TRADE_TYPE,'04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE) = #{bookDate,jdbcType = DATE}
AND NVL(DEAL.FPROD_ID,DEAL.PROD_ID) in
#{accountid}
AND DEAL.CCY = #{ccy,jdbcType=VARCHAR}
AND DEAL.ISSUE_PARTY_ID = #{issuePartyId,jdbcType=VARCHAR}
AND DEAL.TRADE_TYPE IN
#{dealtype}
GROUP BY NVL(DEAL.FPROD_ID,DEAL.PROD_ID), DEAL.ISSUE_PARTY_ID, DECODE(DEAL.TRADE_TYPE,'04',DEAL.INTEREST_DATE,DEAL.SETTDATE_DATE), DEAL.CCY, INFO.PRODTYPE, DEAL.ORG_CODE order by NVL(DEAL.FPROD_ID,DEAL.PROD_ID)

SELECT POS.CDATE+1 CDATE, POS.PROD_ID, POS.CCY, POS.ISSUE_PARTY_ID, CUSTAMT, CUSTQTY, RAISEAMT, POS.BALANCE_QTY, POS.BALANCE_AMT, POS.TOTAL_INTAMT FROM CHB_PRD_POSITION_TOTAL POS WHERE 1 = 1 AND POS.CDATE = #{cdate,jdbcType = DATE}
AND POS.PROD_ID in
#{accountid}
/*未到期且后续没有待支付的付息交易*/ AND NOT EXISTS ( SELECT 1 FROM CHB_PRD_DEAL_TOTAL DL WHERE NVL(FPROD_ID,PROD_ID) = POS.PROD_ID AND DL.SETTDATE_DATE = POS.CDATE AND DL.TRADE_TYPE = '16' AND DL.STATUS != 'D' AND NOT EXISTS (SELECT 1 FROM CHB_PRD_DEAL_TOTAL T1 WHERE T1.PROD_ID = DL.PROD_ID AND T1.TRADE_TYPE = '04' AND T1.STATUS != 'D' AND T1.INTEREST_DATE > DL.SETTDATE_DATE) )

		SELECT
		case 
        when min(SETTDATE_DATE) is  null 
        then #{batchDate,jdbcType=DATE}
        when min(SETTDATE_DATE) is not null and min(SETTDATE_DATE)>#{batchDate,jdbcType=DATE} 
        then #{batchDate,jdbcType=DATE}
        when min(SETTDATE_DATE) is not null and min(SETTDATE_DATE)<=#{batchDate,jdbcType=DATE} 
        then  min(SETTDATE_DATE) end  SETTDATEDATE 
		FROM CHB_PRD_DEAL_TOTAL
		WHERE
			to_char(update_time,'yyyy-MM-dd')=to_char(#{batchDate,jdbcType=DATE},'yyyy-MM-dd')

      	 	AND NVL(FPROD_ID,PROD_ID) in 

	          #{accountid}

select deal.status, NVL(DEAL.FPROD_ID,DEAL.PROD_ID) prodId, deal.fprod_id fprodid, deal.org_code orgCode, deal.trade_type tradeType, deal.settdate_date settdateDate, nvl(deal.TRADE_Amt,0) tradeAmt, nvl(deal.INT_AMT,0) intamt, deal.pay_date payDate, deal.interest_date interestDate, nvl(deal.trade_qty,0) tradeQty, deal.CCY ccy, deal.REDEMPTION_FEE redemptionfee, deal.rev_date revDate, deal.ISSUE_PARTY_ID issuePartyId from chb_prd_deal_total deal where deal.status != 'D'
and settdate_date=#{batchDate,jdbcType=DATE}
NVL(DEAL.FPROD_ID,DEAL.PROD_ID) = #{prodId,jdbcType = VARCHAR}
